package android.app;import android.content.*;import java.util.concurrent.atomic.*;public class PendingIntent {public static final int FLAG_IMMUTABLE=0x04000000;public final Context context;public final Intent intent;public final int flags;public final AtomicInteger cancels=new AtomicInteger();private PendingIntent(Context c,Intent i,int f){context=c;intent=new Intent(i);flags=f;}public static PendingIntent getBroadcast(Context c,int requestCode,Intent i,int flags){return new PendingIntent(c,i,flags);}public void cancel(){cancels.incrementAndGet();}}
